#!/usr/bin/env node
/* MVP Trainer V5 R7.5 - Mobile + Final Control Polish installer */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const root = process.cwd();
const target = path.join(root, "src", "features", "music", "MusicMiniPlayer.tsx");
const expectedCurrentSha256 = "54ec2e949865b5fd8526a50c02529616a036d2587451e1d35bf553b02429cba8";
const expectedReplacementSha256 = "5583684f2064f1819d2788ebbdfa6f8a80d3adbdc41f8263329c69b2759fd5f7";
const replacementBase64 = "";

function sha256(buffer) {
  return crypto.createHash("sha256").update(buffer).digest("hex");
}

function fail(message) {
  console.error(`
R7.5 STOPPED: ${message}
`);
  process.exit(1);
}

if (!fs.existsSync(target)) {
  fail(`Could not find ${path.relative(root, target)}. Run this from the MVP Trainer repo root.`);
}

const current = fs.readFileSync(target);
const currentText = current.toString("utf8");
const currentSha = sha256(current);

if (currentText.includes("MVP_TRAINER_V5_R7_5_MOBILE_FINAL_CONTROL_POLISH")) {
  console.log(`
MVP Trainer V5 R7.5 is already applied. No files changed.
`);
  process.exit(0);
}

if (!currentText.includes("export function MusicMiniPlayer")) {
  fail("The target file does not look like the MVP MusicMiniPlayer. Nothing was changed.");
}

if (currentSha !== expectedCurrentSha256) {
  fail(
    "MusicMiniPlayer.tsx does not exactly match the R7.4 baseline this update was built against. " +
    "Nothing was overwritten. Send the current MusicMiniPlayer.tsx if you intentionally changed it after R7.4."
  );
}

const replacement = Buffer.from(replacementBase64, "base64");
if (sha256(replacement) !== expectedReplacementSha256) {
  fail("Replacement integrity check failed. Nothing was changed.");
}

const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const backup = `${target}.bak-r7-5-${stamp}`;
fs.copyFileSync(target, backup);
fs.writeFileSync(target, replacement);

console.log(`
MVP Trainer V5 R7.5 Mobile + Final Control Polish applied successfully.`);
console.log(`Updated: ${path.relative(root, target)}`);
console.log(`Backup:  ${path.relative(root, backup)}`);
console.log(`SHA-256: ${expectedReplacementSha256}`);
console.log(`
Next: run npm run build, then test desktop + mobile before committing.
`);
